    ax.Layout.Row = [2 3];
    ax.Layout.Column = [1 2];

    % Create status text area
    statusText = uilabel(grid);
    statusText.Text = 'Ready to fetch data...';
    statusText.Layout.Row = 1;
    statusText.Layout.Column = 2;

    function fetchData()
        try
            % Update status
            statusText.Text = 'Fetching data...';
            drawnow;

            % Use webread to fetch data from OpenMeteo API
            % Getting temperature data for London for the last 7 days
            baseURL = 'https://api.open-meteo.com/v1/forecast';
            latitude = '51.5085'; % London latitude
            longitude = '-0.1257'; % London longitude

            % Create the URL with parameters
            url = [baseURL, '?latitude=', latitude, '&longitude=', longitude, ...
                  '&hourly=temperature_2m&past_days=7'];

            % Fetch data
            data = webread(url);

            % Extract time and temperature data
            time = datetime(data.hourly.time, 'InputFormat', 'yyyy-MM-dd''T''HH:mm');
            temp = data.hourly.temperature_2m;

            % Convert time to hours since start for regression
            hoursElapsed = hours(time - time(1));

            % Perform linear regression
            p = polyfit(hoursElapsed, temp, 1);
            yFit = polyval(p, hoursElapsed);

            % Plot the data
            cla(ax);
            plot(ax, time, temp, 'b.', 'DisplayName', 'Actual Temperature');
            hold(ax, 'on');
            plot(ax, time, yFit, 'r-', 'DisplayName', 'Linear Regression');
            hold(ax, 'off');

            % Customize plot
            title(ax, 'Temperature Trend Analysis');
            xlabel(ax, 'Time');
            ylabel(ax, 'Temperature (°C)');
            legend(ax, 'Location', 'best');
            grid(ax, 'on');

            % Update status with regression equation
            slope = p(1);
            intercept = p(2);
            statusText.Text = sprintf('Regression: T = %.2f*h + %.2f\nSlope: %.2f°C/hour', ...
                slope, intercept, slope);

        catch ME
            % Handle any errors
            statusText.Text = ['Error: ' ME.message];
        end
    end
end"}

