        orderSpinner.RoundFractionalValues = true;
        orderSpinner.Value = 1;
        orderSpinner.Layout.Row = 5;
        % Ensure spinner updates trigger a refit when data is available
        orderSpinner.ValueChangedFcn = @orderChanged;

    % Create results panel (bottom)
    resultsPanel = uipanel(controlGrid, 'Title', 'Analysis Results', ...
        'BackgroundColor', 'white');
    resultsPanel.Layout.Row = 6;
    
    % Create results text
    statusText = uilabel(resultsPanel);
